try { const k = CONFIG.lulu?.clientKey || ''; const s = CONFIG.lulu?.clientSecret || ''; CONFIG.lulu.basicAuth = 'Basic ' + Buffer.from(`${k}:${s}`).toString('base64'); } catch (e) {}

