// Validate all sibling PDFs with Lulu + Guard against duplicate submission
const j = $input.first().json || {};
const siblings = j.siblings || [];
const cfg = j.CONFIG || {};
const luluToken = j.luluAccessToken;
const luluBase = cfg.lulu?.apiBase || 'https://api.lulu.com';
const podPackageId = cfg.defaults?.podPackageId || '0850X0850FCPRESS080CW444MXX';
const http = this.helpers.httpRequest;
const AUTH = { 'Content-Type': 'application/json', Authorization: `Bearer ${luluToken}` };

// ── PHASE 1: Validate every sibling's interior + cover with Lulu ──
const validationErrors = [];
for (let i = 0; i < siblings.length; i++) {
  const s = siblings[i];
  try {
    const intResp = await http({
      method: 'POST', url: `${luluBase}/validate-interior/`, json: true,
      headers: AUTH, body: { source_url: s.interiorSignedUrl, pod_package_id: podPackageId },
