  } catch (e) {
    validationErrors.push(`Sibling ${s.orderId} cover validation failed: ${e.message}`);
  }
}
if (validationErrors.length) {
  throw new Error(`Lulu PDF validation failed:\n${validationErrors.join('\n')}`);
}

