      method: 'GET',
      url: `${supaUrl}/rest/v1/orders?or=(${orFilter})&select=orderId,lulu_job_id,lulu_status&lulu_job_id=not.is.null`,
      headers: { apikey: supaKey, Authorization: `Bearer ${supaKey}` },
      json: true, ignoreHttpStatusErrors: true
    });
    if (Array.isArray(rows) && rows.length > 0) {
      const existing = rows.map(r => `${r.orderId}: job=${r.lulu_job_id}`).join(', ');
