// Build Error Context — recover sibling IDs and emit N items for per-row error handling
const execData = $json.execution || {};
const err = execData.error || $json.error || {};
const runData = execData.data?.resultData?.runData || execData.data?.runData || {};

function findField(fieldNames) {
  const names = Array.isArray(fieldNames) ? fieldNames : [fieldNames];
  for (const [_, runs] of Object.entries(runData || {})) {
    if (!Array.isArray(runs)) continue;
    for (const run of runs) {
      for (const item of (run.data?.main?.[0] || [])) {
        const j = item.json || {};
        for (const name of names) {
          if (j[name] !== undefined && j[name] !== null && String(j[name]).trim() !== '') return j[name];
        }
      }
    }
  }
}

function findConfig() {
  for (const [_, runs] of Object.entries(runData || {})) {
    for (const run of runs || []) {
      for (const item of (run.data?.main?.[0] || [])) { if (item.json?.CONFIG) return item.json.CONFIG; }
    }
  }
}

function findSiblingOrderIds() {
  const configRuns = runData['Config + Validate Sibling Group'];
  if (!Array.isArray(configRuns)) return [];
  const ids = [];
  for (const run of configRuns) { for (const item of (run.data?.main?.[0] || [])) { if (item.json?.orderId) ids.push(item.json.orderId); } }
  return ids;
}

const CONFIG = findConfig() || {};
const siblingOrderIds = findSiblingOrderIds();
const phase = err.node?.name || execData.lastNodeExecuted || 'unknown';
const safeMessage = String(err.message || err.description || 'Unknown error').slice(0, 800);
const supabaseProjectUrl = CONFIG.supabase?.projectUrl || 'https://mdnthwpcnphjnnblbvxk.supabase.co';
const supabaseServiceRoleKey = CONFIG.supabase?.serviceRoleKey || '';

